import { flushPromises, mount } from '@vue/test-utils'
import { createI18n } from 'vue-i18n'
import { afterEach, describe, expect, it, vi } from 'vitest'

import ChannelFormModal from '@/components/console/channels/ChannelFormModal.vue'
import { ADMIN_CHANNEL_TYPE_META } from '@/constants/adminChannels'
import type { AdminChannel } from '@/types/console'
// Generated by controller/frontend_contract_test.go: the native type ids and a
// request that the real UpdateChannel accepts for a type outside the create list.
import nativeTypes from '../../../../../tests/fixtures/native/channel-type-ids.json'
import nativeRename from '../../../../../tests/fixtures/native/channel-native-type-rename.put.request.json'

vi.mock('@/api/adminManagement', () => ({
  metadataApi: { groups: vi.fn().mockResolvedValue([]) },
}))
vi.mock('@/stores/auth', () => ({
  useAuthStore: () => ({
    isAdmin: true,
    hasPermission: (resource: string) =>
      resource === 'channel' || resource === 'task_plugin',
  }),
}))
vi.mock('@/stores/app', () => ({
  useAppStore: () => ({
    isFeatureEnabled: () => true,
    featureStatus: () => 'live',
  }),
}))
vi.mock('@/features/task-plugins/api', () => ({
  getTaskPluginOptions: vi.fn().mockResolvedValue([]),
}))

// The create list Ren2Hub configures end to end; it must not grow by accident.
const CREATABLE_LABELS = [
  'OpenAI',
  'Azure',
  'Ollama',
  'Anthropic',
  'Ali',
  'OpenRouter',
  'Gemini',
  'Moonshot',
  'AWS Bedrock',
  'SiliconFlow',
  'Vertex AI',
  'DeepSeek',
  'xAI',
  'Advanced Custom',
  'Sub2API',
  'New API',
  'Task Plugin',
  'vLLM',
  'SGLang',
]

function channel(overrides: Partial<AdminChannel>): AdminChannel {
  return {
    id: nativeRename.id,
    name: 'native-contract',
    type: nativeRename.type,
    channel_ratio: '1',
    max_concurrency: 0,
    in_flight: 0,
    supplier: '',
    lab: { id: 'unknown', name: 'Unknown', source: 'unknown' },
    status: 1,
    priority: 0,
    weight: 1,
    used_quota: 0,
    balance: 0,
    response_time: 0,
    test_time: 0,
    base_url: nativeRename.base_url,
    models: nativeRename.models,
    model_mapping: '',
    other: 'contract-library',
    settings: '{"allow_service_tier":true}',
    ...overrides,
  }
}

const query = <T extends Element>(selector: string) =>
  document.body.querySelector<T>(`[role="dialog"] ${selector}`)
const dialogText = () =>
  document.body.querySelector('[role="dialog"]')?.textContent ?? ''

let wrapper: { unmount: () => void } | null = null
afterEach(() => {
  wrapper?.unmount()
  wrapper = null
  document.body.innerHTML = ''
})

async function openForm(editing: AdminChannel | null) {
  const save = vi.fn().mockResolvedValue(true)
  wrapper = mount(ChannelFormModal, {
    attachTo: document.body,
    props: { open: true, editing, save, fetchModels: vi.fn() },
    global: {
      plugins: [
        createI18n({
          legacy: false,
          locale: 'en',
          missingWarn: false,
          fallbackWarn: false,
        }),
      ],
    },
  })
  await flushPromises()
  return save
}

const typeButton = () => query<HTMLButtonElement>('button[aria-expanded]')!
const saveButton = () =>
  [
    ...document.body.querySelectorAll<HTMLButtonElement>(
      '[role="dialog"] button'
    ),
  ].find((button) => button.textContent?.includes('channels.saveChannel'))!

async function rename(name: string) {
  const input = query<HTMLInputElement>('input[name="admin-channel-name"]')!
  input.value = name
  input.dispatchEvent(new Event('input'))
  await flushPromises()
}

describe('channel type catalog', () => {
  it('names every native type and keeps the retired 57', () => {
    const named = Object.keys(ADMIN_CHANNEL_TYPE_META)
      .map(Number)
      .filter((id) => ADMIN_CHANNEL_TYPE_META[id]?.retired !== true)
    expect(named).toEqual(nativeTypes.ids)
    expect(ADMIN_CHANNEL_TYPE_META[57]?.retired).toBe(true)
  })

  it('offers only the configured types when creating', async () => {
    await openForm(null)
    typeButton().click()
    await flushPromises()
    const options = [
      ...document.body.querySelectorAll('[role="listbox"] [role="option"]'),
    ].map((option) => option.textContent?.trim() ?? '')
    expect(options).toHaveLength(CREATABLE_LABELS.length)
    for (const label of CREATABLE_LABELS)
      expect(options.some((text) => text.endsWith(label))).toBe(true)
    expect(options.some((text) => text.endsWith('Baidu'))).toBe(false)
  })
})

describe('editing a type outside the create list', () => {
  it('saves AI Proxy Library common fields as UpdateChannel accepts', async () => {
    const save = await openForm(channel({}))
    expect(typeButton().textContent).toContain('AI Proxy Library')
    expect(typeButton().disabled).toBe(true)
    expect(dialogText()).toContain('channels.typeNotCreatable')
    await rename(nativeRename.name)
    saveButton().click()
    await flushPromises()
    expect(save).toHaveBeenCalledOnce()
    // useAdminChannels.updateChannelDetails adds the id before the PUT; the
    // stored other and settings stay untouched because they are not sent.
    expect({ id: nativeRename.id, ...save.mock.calls[0]![0] }).toEqual(
      nativeRename
    )
  })

  it('keeps a Baidu channel on type 15', async () => {
    const save = await openForm(channel({ type: 15, name: 'baidu' }))
    expect(typeButton().textContent).toContain('Baidu')
    await rename('baidu-renamed')
    saveButton().click()
    await flushPromises()
    expect(save).toHaveBeenCalledWith(
      expect.objectContaining({ type: 15, name: 'baidu-renamed' })
    )
    expect(save.mock.calls[0]![0]).not.toHaveProperty('other')
    expect(save.mock.calls[0]![0]).not.toHaveProperty('settings')
  })

  it('blocks saving a type the console does not know', async () => {
    const save = await openForm(channel({ type: 99 }))
    expect(typeButton().textContent).toContain('channels.unknownType')
    expect(query('[role="alert"]')?.textContent).toContain(
      'channels.unknownTypeCannotSave'
    )
    await rename('unknown-renamed')
    expect(saveButton().disabled).toBe(true)
    saveButton().click()
    await flushPromises()
    expect(save).not.toHaveBeenCalled()
  })
})
